const issueRows = $('Read recent Paperclip tasks').all().map(({ json }) => json);
const runRows = $('Read active Paperclip runs').all().map(({ json }) => json);
const issues = issueRows.flatMap((row) => Array.isArray(row) ? row : (Array.isArray(row.issues) ? row.issues : [row.issue ?? row]));
const runs = runRows.flatMap((row) => Array.isArray(row) ? row : (Array.isArray(row.runs) ? row.runs : [row.run ?? row]));
if (issues.some((item) => typeof item !== 'object' || item === null) || runs.some((item) => typeof item !== 'object' || item === null)) throw new Error('Paperclip returned an unexpected task or run list.');
const safeRuns = runs.filter((run) => run.id || run.runId).map((run) => ({
  id: String(run.id ?? run.runId),
  issueId: run.issueId ? String(run.issueId) : null,
  agentId: run.agentId ? String(run.agentId) : null,
  status: String(run.status ?? 'unknown'),
  startedAt: run.startedAt ?? null,
  endedAt: run.endedAt ?? run.finishedAt ?? null,
}));
const safeTasks = issues.filter((issue) => issue.id || issue.identifier).map((issue) => {
  const id = String(issue.id ?? '');
  return {
    id,
    identifier: String(issue.identifier ?? ''),
    title: String(issue.title ?? 'بدون عنوان').slice(0, 240),
    status: String(issue.status ?? 'unknown'),
    priority: String(issue.priority ?? 'unknown'),
    assigneeAgentId: issue.assigneeAgentId ? String(issue.assigneeAgentId) : null,
    projectId: issue.projectId ? String(issue.projectId) : null,
    createdAt: issue.createdAt ?? null,
    updatedAt: issue.updatedAt ?? null,
    activeRuns: safeRuns.filter((run) => run.issueId === id),
  };
});
return [{ json: { source: 'paperclip', companyId: '15af0af3-1b60-4bbb-8dc3-f969c2206ea4', n8nExecutionId: String($execution.id), observedAt: new Date().toISOString(), taskCount: safeTasks.length, activeRunCount: safeRuns.length, tasks: safeTasks, changesMade: false, agentRunsStarted: false } }];
